effect.shader:
float animatedPixelHash(vec2 pixel, float frameSeed) {
vec3 p3 = fract(vec3(pixel.xyx) * 0.1031 + frameSeed * vec3(0.0973, 0.1099, 0.1379));
p3 += dot(p3, p3.yzx + 33.33);
return fract((p3.x + p3.y) * p3.z);
}
void main() {
vec4 source = texture2DCv(inputImg.texture, acScreenNorm);
float frameSeed = floor(acTime * 12.0);
float coverage = step(animatedPixelHash(floor(gl_FragCoord.xy), frameSeed), clamp(source.a, 0.0, 1.0));
gl_FragColor = vec4(source.rgb * coverage, coverage);
}
